 const book=new THREE.Group();scene.add(book);scene.add(new THREE.HemisphereLight(0xffffff,0x718093,2));const light=new THREE.DirectionalLight(0xffffff,2.5);light.position.set(-2,3,6);scene.add(light);
 const w=c.trimWidthMm/c.trimHeightMm*2,h=2,depth=Math.max(.015,c.spineMm/c.trimHeightMm*2);let closed=false,epoch=0,busy=false,animation=0,index=Math.max(0,spreads.findIndex(s=>s.left?.id===project.activePage||s.right?.id===project.activePage)),textures=[],canvases=[];
 function draw(){if(!closed)renderer.render(scene,camera);}
